import {cleanAppearance,appearancePalette,drawGiftBackground} from './appearance.js';
import {labelColors,paintPhotoMount,paintCustomBorder,paintOccasionOrnaments,mimoLabel,mimoPhotoTabs,mimoSeal} from './gift-identity.js';
import {drawWrapped} from './text-layout.js';
export const bookFinishes={
 ivory:{label:'Linho marfim',kind:'linen',color:'#d9c7aa',ink:'#473425',foil:'#c6a46c',roughness:.87},
 cocoa:{label:'Trama de cacau',kind:'buckram',color:'#51382c',ink:'#f2ddba',foil:'#d4b67f',roughness:.82},
 midnight:{label:'Linho azul noite',kind:'linen',color:'#283f50',ink:'#f6e8ce',foil:'#d6b786',roughness:.88},
 plum:{label:'Couro vegano amora',kind:'leather',color:'#533747',ink:'#f7e6d5',foil:'#dbb7a1',roughness:.71},
 clay:{label:'Trama terracota',kind:'buckram',color:'#8f513b',ink:'#fff1d6',foil:'#e1c293',roughness:.84},
 paper:{label:'Papel de algodão',kind:'cotton',color:'#e5d9c4',ink:'#543f2f',foil:'#aa814c',roughness:.96}
};
export function cleanBookFinish(value={}){const v=value&&typeof value==='object'?value:{};return {material:Object.hasOwn(bookFinishes,v.material)?v.material:'ivory',foil:['gold','silver','ink'].includes(v.foil)?v.foil:'gold',ribbon:v.ribbon!==false};}
export function resolveBookFinish(data={}){return cleanBookFinish(data.bookFinish||{material:({cacau:'cocoa',noite:'cocoa',azul:'midnight',ceu:'midnight',amora:'plum',lavanda:'plum',coral:'clay',terracota:'clay'})[data.appearance?.palette]||'ivory'});}
export function bookTexturePaths(value){const finish=bookFinishes[cleanBookFinish(value).material];return ['albedo.webp','normal.png','roughness.webp'].map(map=>'assets/book-'+finish.kind+'-'+map);}
export function paintBookCover(canvas,data,{photo=null,photos=[],sprite=null,cloth=null,pattern=null,maskCanvas=null}={}){
 const finish=resolveBookFinish(data),baseMaterial=bookFinishes[finish.material],custom=cleanAppearance(data.appearance),material={...baseMaterial,...(custom.bookCustom?{color:custom.bookColor}:{}),...(custom.custom||custom.bookCustom?{ink:appearancePalette({...custom,custom:true,paper:custom.bookCustom?custom.bookColor:baseMaterial.color}).ink}:{}),...(custom.coverSurface==='paper'?{ink:appearancePalette(custom).ink}:{})},ctx=canvas.getContext('2d'),w=600,h=800,design=data.stationeryDesign||{},layout=design.layout||'editorial',name=data.recipient||'A nossa história',title=design.title||'Um livro de memórias',gold=finish.foil==='silver'?(finish.material==='ivory'||finish.material==='paper'?'#5d666a':'#dce1dc'):finish.foil==='ink'?material.ink:material.foil;
 const mask=maskCanvas?.getContext('2d');if(mask){maskCanvas.width=canvas.width;maskCanvas.height=canvas.height;mask.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);mask.fillStyle='#000';mask.fillRect(0,0,w,h);}
 ctx.save();ctx.setTransform(canvas.width/w,0,0,canvas.height/h,0,0);ctx.fillStyle=material.color;ctx.fillRect(0,0,w,h);if(cloth){ctx.save();ctx.globalCompositeOperation='multiply';ctx.globalAlpha=.22;ctx.drawImage(cloth,0,0,w,h);ctx.restore();}
 const appearance=cleanAppearance(data.appearance),palette=appearancePalette(appearance);if(appearance.coverSurface==='paper')drawGiftBackground(ctx,w,h,{palette,background:appearance.background,intensity:appearance.intensity,pattern});paintOccasionOrnaments(ctx,w,h,data,appearance.coverSurface==='paper'?palette:{ink:material.ink,accent:gold,soft:material.color});
 // Cloth stays visible; only the photograph is mounted on a paper mat.
 const foil=(text,x,y,width,size,lines=2,serif=true,align='center')=>{for(const [c,isMask]of [[ctx,false],[mask,true]]){if(!c)continue;c.save();c.textBaseline='top';c.textAlign=align;c.font=(serif?'700 ':'700 ')+size+'px '+(serif?(appearance.fontFamily==='clean'?'Nunito,Arial':appearance.fontFamily==='classic'?'Georgia,serif':'Fraunces,Georgia'):'Nunito,Arial');if(!isMask&&finish.foil!=='ink'){c.shadowColor='rgba(0,0,0,.25)';c.shadowBlur=.6;c.shadowOffsetY=.7;}c.fillStyle=isMask?'#fff':material.ink;drawWrapped(c,text,x,y,width,size*1.2,lines);c.restore();}};
 const line=(x,y,width)=>{for(const [c,isMask]of [[ctx,false],[mask,true]]){if(!c)continue;c.fillStyle=isMask?'#fff':gold;c.fillRect(x,y,width,1.4);}};
 const frame=(img,x,y,width,height,tilt=0)=>{if(img&&design.fit!=='cover'){const ratio=Math.min(width/img.width,height/img.height),naturalW=img.width*ratio,naturalH=img.height*ratio;x+=(width-naturalW)/2;y+=(height-naturalH)/2;width=naturalW;height=naturalH;}ctx.save();ctx.translate(x+width/2,y+height/2);ctx.rotate(tilt);const mount=paintPhotoMount(ctx,-width/2-8,-height/2-8,width+16,height+16,data,{...palette,ink:material.ink});ctx.fillStyle='#e5d7c1';ctx.fillRect(-width/2,-height/2,width,height);if(img){const scale=design.fit==='cover'?Math.max(width/img.width,height/img.height):Math.min(width/img.width,height/img.height),iw=img.width*scale,ih=img.height*scale;ctx.save();ctx.beginPath();ctx.roundRect(-width/2,-height/2,width,height,mount.radius);ctx.clip();ctx.drawImage(img,-iw/2,-ih/2,iw,ih);ctx.restore();}else{ctx.fillStyle=material.ink;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='22px Fraunces,Georgia';ctx.fillText('Suas lembranças aqui',0,0);}if(appearance.showTape)mimoPhotoTabs(ctx,-width/2-8,-height/2-8,width+16,height+16,{ink:material.ink,color:appearance.tapeColor});ctx.restore();};
 const initials=name.split(/\s+(?:e|&)\s+|\s+/).filter(word=>word.length>1).slice(0,2).map(word=>Array.from(word)[0]).join(' · ').toLocaleUpperCase('pt-BR');
 const heading=(y=90)=>{foil(title,300,y,450,26,2);line(274,y+85,52);foil(name,300,y+115,458,39,2);};
 if(layout==='poster'){frame(photo,105,95,390,345);foil(title,300,510,440,26,2);line(274,590,52);foil(name,300,620,450,36,2);}else if(layout==='janela'){foil(title,300,70,440,24,2);frame(photo,150,205,300,345);foil(name,300,610,450,36,2);line(244,688,112);}
 else if(layout==='arquivo'){foil(title,68,102,165,28,4,true,'left');frame(photo,270,155,245,385);foil(name,68,565,465,37,2,true,'left');line(68,691,90);}
 else if(layout==='colagem'){heading(70);frame(photo,83,365,265,230,-.035);frame(photos.find(img=>img&&img!==photo)||photo,327,490,178,164,.035);}else if(layout==='dupla'){heading(65);frame(photo,76,367,200,260);frame(photos.find(img=>img&&img!==photo)||photo,320,410,200,260);line(274,695,52);}
 else if(layout==='carta'){heading(100);frame(photo,105,402,210,230);foil('Para guardar\npor perto.',360,450,145,24,3,true,'left');line(360,575,58);}
 else if(layout==='jornal'){foil((data.theme?.label||'MEMÓRIAS').toLocaleUpperCase('pt-BR'),68,72,470,13,1,false,'left');foil(name,68,125,465,48,2,true,'left');line(68,267,464);frame(photo,82,319,436,280);foil(title,68,665,465,25,2,true,'left');}
 else if(layout==='faixa'){heading(70);frame(photo,55,370,490,235);}
 else{heading(82);frame(photo,110,375,380,265);if(layout==='lembranca'){line(88,735,424);}else if(appearance.borderStyle==='theme'){for(const c of [ctx,mask])if(c){c.strokeStyle=c===mask?'#fff':gold;c.lineWidth=appearance.borderWidth;c.beginPath();c.roundRect(43,43,514,714,20);c.stroke();}}}
 if(appearance.borderStyle!=='theme'&&appearance.borderStyle!=='none')paintCustomBorder(ctx,w,h,palette,appearance);if(appearance.showLabels)mimoLabel(ctx,'feito com carinho',214,29,172,31,labelColors(data,'#fff2ce'));if(mask){mask.fillStyle='#000';mask.fillRect(211,26,178,37);}
 foil(design.closing||'Uma história para guardar.',300,720,420,12,2,false);
 if(design.seal!==false&&data.character!=='none'&&sprite){mimoSeal(ctx,sprite,data.theme,553,739,51,{paper:'#fff9f1',ink:'#3a1e14',accent:'#e8473a'});if(mask){mask.fillStyle='#000';mask.fillRect(518,703,70,72);}}
 ctx.restore();return {finish:finish.material,layout,foil:finish.foil};
}
export function roundedBookGeometry(THREE,width,height,depth,radius=.035){
 const x=-width/2,y=-height/2,r=Math.min(radius,width/5,height/5),shape=new THREE.Shape();shape.moveTo(x+r,y);shape.lineTo(x+width-r,y);shape.quadraticCurveTo(x+width,y,x+width,y+r);shape.lineTo(x+width,y+height-r);shape.quadraticCurveTo(x+width,y+height,x+width-r,y+height);shape.lineTo(x+r,y+height);shape.quadraticCurveTo(x,y+height,x,y+height-r);shape.lineTo(x,y+r);shape.quadraticCurveTo(x,y,x+r,y);
 const geometry=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:true,bevelSegments:3,steps:1,bevelSize:.009,bevelThickness:.009,curveSegments:5});geometry.translate(0,0,-depth/2);const positions=geometry.attributes.position,normals=geometry.attributes.normal,uv=geometry.attributes.uv;geometry.clearGroups();let material=-1,start=0;for(let i=0;i<positions.count;i+=3){const z=(normals.getZ(i)+normals.getZ(i+1)+normals.getZ(i+2))/3,index=z>.95?4:z<-.95?5:0;if(index!==material){if(i>start)geometry.addGroup(start,i-start,material);start=i;material=index;}for(let j=0;j<3;j++){const n=i+j;uv.setXY(n,(z<-.95?-positions.getX(n):positions.getX(n))/width+.5,positions.getY(n)/height+.5);}}geometry.addGroup(start,positions.count-start,material);uv.needsUpdate=true;geometry.computeBoundingBox();return geometry;
}
export function initBookFinishEditor({getState,onChange}){
 const panel=document.createElement('section');panel.className='book-finish-editor';panel.innerHTML='<h3>Encadernação do livro</h3><p>Textura de tecido, cantos arredondados e título metalizado. Um álbum digital com acabamento de coleção.</p><div class="book-finish-options" role="group" aria-label="Material da capa"></div><label>Acabamento do título<select class="book-foil"><option value="gold">Champagne metalizado</option><option value="silver">Prata acetinada</option><option value="ink">Tinta fosca</option></select></label><label class="book-ribbon"><input type="checkbox" checked> Fita marcadora de página</label><small>Você está criando um presente digital em 3D.</small>';
 for(const [id,finish]of Object.entries(bookFinishes)){const button=document.createElement('button');button.type='button';button.dataset.bookFinish=id;button.style.setProperty('--finish-color',finish.color);button.style.setProperty('--finish-texture','url(assets/book-'+finish.kind+'-albedo.webp)');button.innerHTML='<span aria-hidden="true"></span><strong></strong>';button.querySelector('strong').textContent=finish.label;button.addEventListener('click',()=>onChange({bookFinish:{...cleanBookFinish(getState().bookFinish),material:id}}));panel.querySelector('.book-finish-options').append(button);}panel.querySelector('.book-foil').addEventListener('change',event=>onChange({bookFinish:{...cleanBookFinish(getState().bookFinish),foil:event.target.value}}));panel.querySelector('.book-ribbon input').addEventListener('change',event=>onChange({bookFinish:{...cleanBookFinish(getState().bookFinish),ribbon:event.target.checked}}));document.querySelector('.appearance-editor').before(panel);
 function render(){panel.hidden=getState().format!=='livro';const finish=resolveBookFinish(getState());panel.querySelectorAll('[data-book-finish]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.bookFinish===finish.material)));panel.querySelector('.book-foil').value=finish.foil;panel.querySelector('.book-ribbon input').checked=finish.ribbon;}render();return {render};
}
